text:
{
  "units": [
    {
      "issue": "U01｜主判断单元：SP-01到账后，三笔债务的可请求余额及各保证人的责任范围",
      "decisive_facts": [
        "材料明确属于虚构衍生情景，不存在可供提取的真实法院裁判结论。",
        "结算截至2023-08-01，不计当日利息；最终核对SP-01到账后的剩余余额。",
        "甲请求A剩余实际交付财产返还、B可保护本息、C剩余本金及合法利息和费用，并请求保证人承担相应责任。",
        "S06另明确将庚列入最终付款请求对象，须与S12合并读取。",
        "各输出分项最终取分后再相加；同一债务的借款人责任与保证责任不得作为不同债权重复累计。"
      ],
      "support_spans": [
        {
          "span_id": "S12",
          "supports": "最终请求范围、不请求保证合同无效后的过错赔偿及分项取分规则。"
        },
        {
          "span_id": "S13",
          "supports": "SP-01已经到账、最终余额时点及不计截日利息。"
        },
        {
          "span_id": "S06",
          "supports": "庚亦为最终付款请求对象，戊庚对外覆盖全部B债务。"
        },
        {
          "source": "material_pack.normalized_text",
          "locator": "导语",
          "supports": "显著虚构标识、2023-08-01新受理及不存在未列明付款等题设边界。"
        }
      ],
      "dependencies": [
        {
          "unit": "U02",
          "relation": "确定A返还债务及丁的合同保证责任。"
        },
        {
          "unit": "U04",
          "relation": "取得SP-01前B的可保护本息。"
        },
        {
          "unit": "U06",
          "relation": "取得SP-01前C的本金、利息和费用余额。"
        },
        {
          "unit": "U09",
          "relation": "完成SP-01债务归属及债务内部抵充。"
        },
        {
          "unit": "U10",
          "relation": "将抵充后余额映射到各主体责任，避免重复汇总。"
        }
      ],
      "answerability": {
        "status": "可提取，完整金额待复算",
        "scope": "可形成一个联动多个必要判断的主单元；本阶段不生成题目或最终金额标签。",
        "public_basis": "S12、S13限定结算对象和时间，S06补充庚的请求范围；责任范围分别由主债务及保证规范确定。"
      }
    },
    {
      "issue": "U02｜A的合同效力、财产返还及丁的从属性保证",
      "decisive_facts": [
        "A于2022-03-11签订，资金来源为甲套取的银行信贷资金，来源已由题设明确。",
        "乙事先不知资金来源，约定利率为6%；两项事实不能代替适用版本要求的效力审查。",
        "票面160000元，实际交付143038.00元；同一到账交易号的收据不是另一笔交付。",
        "乙此前返还20192.00元；双方约定如合同无效，该款全部冲抵返还财产。",
        "丁提供连带保证；甲不请求无效后的其他赔偿或保证过错赔偿。"
      ],
      "support_spans": [
        {
          "span_id": "S01",
          "supports": "成立时间、资金来源、实际交付、乙知情状态、利率及丁保证。"
        },
        {
          "span_id": "S02",
          "supports": "已返还款、附条件清算约定、同交易号收据及请求限制。"
        },
        {
          "span_id": "S12",
          "supports": "不请求保证合同无效后的过错赔偿。"
        },
        {
          "source_id": "lending-2020-12",
          "provision": "13",
          "supports": "套取金融机构贷款转贷的效力规则。"
        },
        {
          "source_id": "civil-code-2020",
          "provision": "157",
          "supports": "无效民事法律行为的财产返还规则。"
        },
        {
          "source_id": "civil-code-2020",
          "provision": "682",
          "supports": "主合同无效对从属性保证合同的影响。"
        }
      ],
      "dependencies": [],
      "answerability": {
        "status": "题设及规范支持",
        "scope": "支持提取A效力、实际交付减已返还的清算结构，以及丁是否承担合同保证责任。",
        "public_basis": "所附2021年起施行版本第13条未将高利转贷或借款人知情列为该项无效条件；返还与保证效力分别适用民法典第157条、第682条。",
        "boundary": "不能进一步推定丁无任何其他民事责任；过错赔偿不在本单元范围内。"
      }
    },
    {
      "issue": "U03｜B的实际本金、成立时点及利率基准",
      "decisive_facts": [
        "B资金为甲合法自有资金。",
        "2022-01-12票面金额197586.00元，其中12406.00元为放款时预扣利息。",
        "乙于同日实际收到185180.00元，题设明确同日成立并起息。",
        "约定年利率13.200%，合同成立时一年期LPR由题设确定为3.70%。",
        "后续结算不构成债务更新，各期沿用原合同利率及原成立时LPR。"
      ],
      "support_spans": [
        {
          "span_id": "S03",
          "supports": "资金来源、票面与实际交付差额、成立及起息日期、利率和LPR。"
        },
        {
          "span_id": "S04",
          "supports": "不另成立债务更新合同，沿用最初利率基准。"
        },
        {
          "source_id": "civil-code-2020",
          "provision": "670",
          "supports": "预扣利息时以实际借款数额返还并计息。"
        },
        {
          "source_id": "civil-code-2020",
          "provision": "679",
          "supports": "自然人借款合同的实际提供借款成立规则。"
        },
        {
          "source_id": "lending-2020-12",
          "provision": "25、26",
          "supports": "利率保护上限及预扣利息本金认定。"
        }
      ],
      "dependencies": [],
      "answerability": {
        "status": "题设及规范支持",
        "scope": "支持以185180.00元作为初始本金，并区分13.20%的约定利率与14.80%的保护上限。",
        "public_basis": "民法典第670条及借贷解释第26条要求排除预扣利息；第25条规定的四倍LPR是上限，不是自动替换合同利率。"
      }
    },
    {
      "issue": "U04｜B逐次结息的合法本金承接、整体上限及SP-01前余额",
      "decisive_facts": [
        "B于2022-07-06、2022-10-17、2023-01-09分别归档新借据，纸面金额分别为210090.76元、217916.49元、224536.38元。",
        "三次新增交付均为0元；双方约定结算前期未付本息，不成立新的债务更新合同。",
        "逐期采用实际自然日/365，计算过程保留全部精度，仅最终输出金额取分。",
        "B原到期日为2023-01-12，甲乙展期至2023-06-30；截日至2023-08-01且不计当日利息。",
        "除SP-01待确定的抵充外，档案未记载其他B还款。"
      ],
      "support_spans": [
        {
          "span_id": "S04",
          "supports": "结息约定、无债务更新、日数和精度规则及其他还款情况。"
        },
        {
          "span_id": "S05",
          "supports": "三次归档日期、纸面金额与零新增交付。"
        },
        {
          "span_id": "S06",
          "supports": "原到期日、展期及保证人对原结息机制的同意。"
        },
        {
          "span_id": "S12",
          "supports": "甲请求全部可保护本息。"
        },
        {
          "span_id": "S13",
          "supports": "结算截日与SP-01付款。"
        },
        {
          "source_id": "lending-2020-12",
          "provision": "27",
          "supports": "合法利息计入后期本金的条件及整个借款期间本息上限。"
        },
        {
          "source_id": "lending-2020-12",
          "provision": "28",
          "supports": "逾期阶段利息的适用规则。"
        }
      ],
      "dependencies": [
        {
          "unit": "U03",
          "relation": "实际本金和原合同利率基准决定各期可承接的本息。"
        }
      ],
      "answerability": {
        "status": "可提取，数值标签待复算",
        "scope": "支持逐期审查合法结息额，再与整体上限比较；不直接沿用纸面本金。",
        "public_basis": "借贷解释第27条分别限制可资本化利息和最终本息总额；零新增交付不能作为新增放款累计。",
        "required_validation": [
          "逐段核对日数及结算日衔接。",
          "核对各纸面金额中缺乏合法本金或利息依据的部分。",
          "分别计算合法结息候选额与整体上限，不能预设任一数值必然控制结果。",
          "独立复算逾期阶段及最终取分。"
        ]
      }
    },
    {
      "issue": "U05｜C旧借款的时间法适用及合法利率分段",
      "decisive_facts": [
        "C于2019-02-07实际交付225740.00元并成立起息，没有预扣利息。",
        "合同年利率23.50%，到期日2022-12-15，逾期仍约定同一利率。",
        "2022年保证文件不构成新借款或债务更新。",
        "甲明确请求对合同成立至2020-08-19的利息适用当时司法解释，其后仅请求法律保护范围内利息。",
        "C各次诉讼受理时一年期LPR均由题设确定为3.25%。"
      ],
      "support_spans": [
        {
          "span_id": "S07",
          "supports": "旧借款成立、利率、到期日、无债务更新、利息请求及诉讼时LPR。"
        },
        {
          "span_id": "S10",
          "supports": "2022年保证成立及2023年两次诉讼时间。"
        },
        {
          "source_id": "lending-2020-12",
          "provision": "31",
          "supports": "新受理旧借款的利息分段过渡规则。"
        },
        {
          "source_id": "lending-2015",
          "provision": "26",
          "supports": "旧规则下不超过年利率24%的约定利息保护标准。"
        },
        {
          "source_id": "lending-2020-12",
          "provision": "25、28",
          "supports": "后段利率保护标准及逾期利息规则。"
        }
      ],
      "dependencies": [],
      "answerability": {
        "status": "题设及规范支持",
        "scope": "支持区分2020-08-20前后的利息规则，并将借款成立与后来保证成立分开。",
        "public_basis": "借贷解释第31条直接规定旧合同利息的过渡处理；依给定LPR，后段保护上限为13.00%，不能继续以23.50%作为全部可强制请求利率。",
        "boundary": "LPR仅作为虚构题设参数使用，不据此陈述现实历史报价。"
      }
    },
    {
      "issue": "U06｜C付款真实性去重、约定抵充顺序及滚动本金余额",
      "decisive_facts": [
        "T-01至T-07均已实际结算并指定偿还C，日期及金额由S08逐笔列明。",
        "实现债权费用1680元于2019-04-17到期，题设确认依法可收取。",
        "原合同约定各笔付款先费用、再依法可请求利息、最后本金。",
        "仅T-02有双方签署的补充协议，改为先本金，再费用和利息。",
        "其他付款的还本金备注仅由乙单方作出，甲未同意。",
        "S11中的T-01截图、收据与S08首行属于同一银行交易号。",
        "X-01未执行、已撤销且未入账；乙关于点击提交即完成的说法为单方主张。",
        "利息按未清偿本金、实际自然日/365单利累计，付款当日不再对已偿本金计息，未付利息不另生息。"
      ],
      "support_spans": [
        {
          "span_id": "S07",
          "supports": "费用、计息基础、单利及付款日规则。"
        },
        {
          "span_id": "S08",
          "supports": "七笔实际结算付款的完整流水。"
        },
        {
          "span_id": "S09",
          "supports": "原抵充约定、T-02例外及其他单方备注未获同意。"
        },
        {
          "span_id": "S11",
          "supports": "同交易号重复记录、X-01未执行及乙的单方主张。"
        },
        {
          "source_id": "civil-code-2020",
          "provision": "561",
          "supports": "适用期间内费用、利息、本金的抵充顺序及当事人约定例外。"
        }
      ],
      "dependencies": [
        {
          "unit": "U05",
          "relation": "合法利率分段决定各付款日前可请求利息，进而影响付款能减少的本金及后续计息。"
        }
      ],
      "answerability": {
        "status": "可提取，逐笔余额待复算",
        "scope": "支持建立费用、合法利息、本金三项账簿，识别T-02例外、T-01重复凭证和X-01未到账。",
        "public_basis": "2019年付款顺序直接有S09原合同和补充协议支持，无须倒溯适用民法典第561条；同一交易的多份凭证不是多笔付款。",
        "required_validation": [
          "在T-04前的计息区间内正确拆分2020-08-20利率切点。",
          "每次付款后更新未清偿本金，不对未付利息计息。",
          "保留T-02例外对后续本金和利息的传导。",
          "以十进制定点方式独立复算最终余额。"
        ]
      }
    },
    {
      "issue": "U07｜B对戊、庚分别行权的效力、内部追偿与对外保证范围",
      "decisive_facts": [
        "戊的原条款要求乙不履行到期债务时即无条件清偿，无须先向乙追索；同份文件明确戊、庚各自对甲保证全部B债务。",
        "戊庚内部约定相互追偿并各分担50%，不是对甲各担一半。",
        "两人均同意原结息机制，均未书面同意展期；保证期间均写为直至本息还清。",
        "B原到期日2023-01-12，甲乙后来展期至2023-06-30。",
        "对戊的诉讼于2023-07-05受理，含完整给付请求的诉状于2023-07-07送达，2023-07-09撤诉。",
        "甲另于2023-07-06向庚提出完整给付请求并实际到达；对戊的诉讼未列庚，也未向庚送达。",
        "庚主张免责，戊主张因丧失对庚追偿而减责；这些是当事人主张，不是已经成立的责任状态。",
        "戊庚财产充足，不存在其他影响内部追偿的事由。"
      ],
      "support_spans": [
        {
          "span_id": "S06",
          "supports": "保证正文、外部范围、内部份额、原到期与展期、逐人行权记录、双方抗辩及履行能力。"
        },
        {
          "source_id": "civil-code-2020",
          "provision": "688、692、693、695",
          "supports": "连带保证、保证期间、行权方式及未经同意展期的影响。"
        },
        {
          "source_id": "guarantee-2020",
          "provision": "25、31、32",
          "supports": "按正文识别类型、已送达后撤诉的效果及还清为止条款的处理。"
        },
        {
          "source_id": "guarantee-2020",
          "provision": "13、29",
          "supports": "内部追偿、逐人行权及丧失追偿减责的条件。"
        }
      ],
      "dependencies": [],
      "answerability": {
        "status": "题设及规范支持",
        "scope": "支持分别审查戊、庚的保证期间与行权，不因存在内部50%份额直接削减对外责任。",
        "public_basis": "民法典第695条规定未经书面同意的展期不影响保证期间；担保解释第31条规定已送达后的撤诉效果，第29条要求分别核对各保证人的行权事实。",
        "boundary": "不得把对戊行权自动扩张到庚；也不得忽略S06中对庚独立且实际到达的请求。"
      }
    },
    {
      "issue": "U08｜C一般保证的期间内再诉、保证存续与先诉抗辩",
      "decisive_facts": [
        "己于2022-02-07承诺乙不能履行、无力偿还时才代偿，没有另约保证期间。",
        "C到期日为2022-12-15。",
        "甲于2023-06-08对乙起诉，2023-06-12撤诉；2023-06-14重新对乙起诉并有效受理，截至截日未审判。",
        "甲于2023-05-08只向己催告。",
        "己在2023-06-25催告书上仅确认收件并明确不确认付款义务，没有新的保证协商或承诺。",
        "乙有可供执行财产，没有民法典第687条所列例外，己未放弃先诉抗辩。",
        "两次诉讼均无已执行款；己财产状况充足。"
      ],
      "support_spans": [
        {
          "span_id": "S07",
          "supports": "C原到期日及保证不构成债务更新。"
        },
        {
          "span_id": "S10",
          "supports": "保证正文、起诉撤诉再诉链、催告及收件签名、未审判执行和先诉抗辩条件。"
        },
        {
          "span_id": "S06",
          "supports": "己的担保履行能力与价值无争议。"
        },
        {
          "source_id": "civil-code-2020",
          "provision": "687、691、692、693",
          "supports": "一般保证、默认范围、期间及对债务人起诉的要求。"
        },
        {
          "source_id": "guarantee-2020",
          "provision": "25、31、34",
          "supports": "保证类型、撤诉后期间内再诉及签字与新保证合同的区分。"
        }
      ],
      "dependencies": [],
      "answerability": {
        "status": "题设及规范支持",
        "scope": "支持分别提取保证是否存续、是否成立新保证、能否要求立即清偿三个状态。",
        "public_basis": "担保解释第31条要求检查撤诉后是否在保证期间内再诉；民法典第687条的先诉抗辩不等于保证消灭。",
        "boundary": "不能仅因己暂有拒绝立即清偿的权利，就将C视为无担保；收件签名也不能单独证明新的保证承诺。"
      }
    },
    {
      "issue": "U09｜SP-01的B/C债务选择及选定债务内部抵充",
      "decisive_facts": [
        "2023-08-01实际到账25000.00元，与T系列和X-01交易号均不同。",
        "双方明确该款仅清偿B、C，不用于A；未具体指定B或C。",
        "双方共同签署附件：两债务均到期且有同等资信的全额保证时，按付款日依法可强制请求的年利率优先清偿较高者；其他情形依法处理。",
        "B、C除各自保证合同外没有抵押、质押或其他担保。",
        "两债务截至付款日均已到期，保证人财产与依法存续担保的价值无争议。"
      ],
      "support_spans": [
